"""Build the French-first V6 pages and their reviewed four-language copy."""
from pathlib import Path
import json,re,html
from pipeline_content import build_pipeline_content
root=Path(__file__).resolve().parents[1]
catalog=json.loads((root/'i18n/static.json').read_text())
def T(fr,en,pt,es):
 catalog[fr]={'en':en,'pt-BR':pt,'es':es};return html.escape(fr)
def P(*a):return '<p>'+T(*a)+'</p>'
def H(*a,level=2):return f'<h{level}>'+T(*a)+f'</h{level}>'
def A(url,*a,cls='cta-button'):return f'<a class="{cls}" href="{html.escape(url,quote=True)}">'+T(*a)+'</a>'
def section(body,id=''):return f'<section'+(f' id="{id}"' if id else '')+'>'+body+'</section>'
def card(body):return '<article class="card">'+body+'</article>'
nav=[('index','Accueil','Home','Início','Inicio'),('solutions','Vos besoins','Your needs','Suas necessidades','Sus necesidades'),('pipelines','Nos pipelines en action','Our pipelines in action','Nossos pipelines em ação','Nuestros pipelines en acción'),('approche','Comment nous travaillons','How we work','Como trabalhamos','Cómo trabajamos'),('realisations','Exemples concrets','Practical examples','Exemplos práticos','Ejemplos prácticos'),('diagnostic','Faire le point','Review your situation','Avalie sua situação','Revise su situación'),('contact','Contact','Contact','Contato','Contacto')]
brand=T('CLN Performance','CLN Performance','CLN Performance','CLN Performance')
footer=T('CLN Performance relie vos applications et enrichit vos données pour valoriser votre SI existant.','CLN Performance connects your applications and enriches your data to unlock the value of your existing IT ecosystem.','A CLN Performance conecta suas aplicações e enriquece seus dados para valorizar seu ecossistema de TI existente.','CLN Performance conecta sus aplicaciones y enriquece sus datos para aprovechar su ecosistema informático existente.')
contact_label=('Parlons de votre situation','Let’s discuss your situation','Vamos conversar sobre sua situação','Hablemos de su situación')
examples_label=('Voir des exemples concrets','See practical examples','Ver exemplos práticos','Ver ejemplos prácticos')
commercial=P('Notre objectif est un bénéfice durable et votre autonomie. Nous ne cherchons pas à installer une facturation récurrente. Selon votre projet, nous pouvons convenir d’une rémunération liée aux bénéfices effectivement constatés, avec des critères définis ensemble avant l’intervention.','Our aim is a lasting benefit and your autonomy. We do not seek to establish recurring billing. Depending on your project, we can agree on remuneration linked to benefits actually observed, with criteria defined together before work begins.','Nosso objetivo é um benefício duradouro e sua autonomia. Não buscamos estabelecer cobranças recorrentes. Conforme o projeto, podemos acordar uma remuneração ligada aos benefícios efetivamente constatados, com critérios definidos em conjunto antes da intervenção.','Nuestro objetivo es un beneficio duradero y su autonomía. No buscamos establecer una facturación recurrente. Según el proyecto, podemos acordar una remuneración vinculada a los beneficios efectivamente constatados, con criterios definidos juntos antes de intervenir.')
def page(name,title,desc,body,scripts=()):
 fulltitle=html.unescape(title)+' — CLN Performance'
 if html.unescape(title) in catalog:catalog[fulltitle]={lang:value+' — CLN Performance' for lang,value in catalog[html.unescape(title)].items()}
 source=root/f'{name}.html'
 head=source.read_text() if source.exists() else f'<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width, initial-scale=1.0"/><title></title><meta name="description" content=""/><link rel="canonical" href="https://cln-performance.com/{name}.html"/><link rel="stylesheet" href="styles.css?v=20261029-v6"/><script defer src="site.js?v=20261029-v6"></script></head><body><header></header><main></main><footer></footer></body></html>'
 # Keep the legal/contact backend contract; pages generated here are editorial.
 head=re.sub(r'<title>.*?</title>','<title>'+title+' — CLN Performance</title>',head,flags=re.S)
 head=re.sub(r'<meta name="description" content="[^"]*"\s*/?>','<meta name="description" content="'+desc+'" />',head)
 header='<header><div class="navbar"><a class="brand" href="index.html"><img src="LOGO_CLN.png" alt="Logo CLN" width="42" height="42"/><span>'+brand+'</span></a><nav class="nav-links" aria-label="'+T('Navigation principale','Main navigation','Navegação principal','Navegación principal')+'">'
 for n,*labels in nav:header+=A(n+'.html',*labels,cls='active' if n==name else '')
 header+='</nav>'+A('contact.html',*contact_label)+'</div></header>'
 foot='<footer><div class="footer-inner"><p>'+footer+'</p><div class="footer-links"><a href="mailto:contact@cln-performance.com">contact@cln-performance.com</a>'+A('contact.html',*contact_label,cls='')+A('mentions-legales.html','Mentions légales','Legal notice','Aviso legal','Aviso legal',cls='')+A('confidentialite.html','Confidentialité','Privacy','Privacidade','Privacidad',cls='')+'</div></div></footer>'
 head=re.sub(r'<header>.*?</header>',header,head,flags=re.S)
 head=re.sub(r'<main\b[^>]*>.*?</main>','<main id="main-content">'+body+'</main>',head,flags=re.S)
 head=re.sub(r'<footer>.*?</footer>',foot,head,flags=re.S)
 head=re.sub(r'<script defer src="(?:diagnostic|contact)\.js[^\"]*">\s*</script>\s*','',head)
 for script in scripts:head=head.replace('</head>',f'<script defer src="{script}.js?v=20261029-v6"></script>\n</head>')
 head=re.sub(r'\?v=202610(?:28-v[23]|29-v[456])','?v=20261029-v6',head)
 if 'class="skip-link"' not in head:head=head.replace('<body>','<body>'+A('#main-content','Aller au contenu','Skip to content','Ir para o conteúdo','Ir al contenido',cls='skip-link'))
 (root/f'{name}.html').write_text(re.sub(r'>\s*<','>\n<',head))
 return header,foot
needs=[
('ressaisies',('Relier vos applications existantes','Connect your existing applications','Conectar suas aplicações existentes','Conectar sus aplicaciones existentes'),('Vos applications détiennent des informations complémentaires. CLN organise leur circulation pour que chaque outil bénéficie des données utiles déjà présentes dans votre SI.','Your applications hold complementary information. CLN organises its flow so each tool benefits from useful data already in your IT ecosystem.','Suas aplicações contêm informações complementares. A CLN organiza sua circulação para que cada ferramenta aproveite os dados úteis já presentes no seu ambiente de TI.','Sus aplicaciones contienen información complementaria. CLN organiza su circulación para que cada herramienta aproveche los datos útiles ya presentes en su SI.'),('Résultat recherché : alimenter vos applications à partir des sources disponibles, via leurs interfaces existantes lorsque cela est possible.','Expected outcome: feed your applications from available sources through existing interfaces where feasible.','Resultado esperado: alimentar suas aplicações com as fontes disponíveis por meio das interfaces existentes quando possível.','Resultado esperado: alimentar sus aplicaciones con las fuentes disponibles mediante interfaces existentes cuando sea posible.')),
('repetitif',('Enrichir les données au fil du parcours','Enrich data throughout its journey','Enriquecer os dados ao longo do percurso','Enriquecer los datos a lo largo del recorrido'),('Une donnée prend de la valeur lorsqu’elle est complétée par un contexte, une règle métier ou un calcul. Le pipeline construit cet enrichissement progressivement entre vos applications.','Data gains value when supplemented by context, a business rule or a calculation. The pipeline builds this enrichment progressively between your applications.','Um dado ganha valor quando é complementado por contexto, uma regra de negócio ou um cálculo. O pipeline constrói esse enriquecimento progressivamente entre suas aplicações.','Un dato gana valor cuando se completa con contexto, una regla de negocio o un cálculo. El pipeline construye este enriquecimiento progresivamente entre sus aplicaciones.'),('Résultat recherché : une information contextualisée et directement exploitable à destination.','Expected outcome: contextualised information ready for use at its destination.','Resultado esperado: informação contextualizada e pronta para uso no destino.','Resultado esperado: información contextualizada y lista para utilizar en destino.')),
('chiffres',('Construire une information cohérente','Build consistent information','Construir informações coerentes','Construir información coherente'),('Deux services annoncent des chiffres différents pour la même activité. CLN clarifie les sources, les définitions et les contrôles pour disposer d’informations cohérentes.','Two departments report different figures for the same activity. CLN clarifies sources, definitions and checks to provide consistent information.','Dois setores apresentam números diferentes para a mesma atividade. A CLN esclarece fontes, definições e controles para obter informações coerentes.','Dos departamentos presentan cifras distintas para la misma actividad. CLN aclara fuentes, definiciones y controles para disponer de información coherente.'),('Bénéfice attendu : comprendre les indicateurs et décider sur une base partagée.','Expected benefit: understand indicators and make decisions on a shared basis.','Benefício esperado: entender os indicadores e decidir com uma base compartilhada.','Beneficio esperado: comprender los indicadores y decidir sobre una base compartida.')),
('suivi',('Créer de la valeur dans vos outils métier','Create value in your business tools','Criar valor nas suas ferramentas de trabalho','Crear valor en sus herramientas de gestión'),('Les données enrichies rejoignent la ou les applications qui en ont besoin : une priorité dans la planification, un dossier complété dans la gestion ou un indicateur dans le pilotage.','Enriched data reaches the applications that need it: a priority in planning, a completed case in case management or an indicator in reporting.','Os dados enriquecidos chegam às aplicações que precisam deles: uma prioridade no planejamento, um processo complementado na gestão ou um indicador no acompanhamento.','Los datos enriquecidos llegan a las aplicaciones que los necesitan: una prioridad en planificación, un expediente completado en gestión o un indicador en seguimiento.'),('Résultat recherché : rendre une décision ou une action possible dans les outils que vos équipes utilisent déjà.','Expected outcome: enable a decision or action in the tools your teams already use.','Resultado esperado: viabilizar uma decisão ou ação nas ferramentas que suas equipes já utilizam.','Resultado esperado: hacer posible una decisión o acción en las herramientas que sus equipos ya utilizan.'))]
