('goal',('Quelle amélioration serait la plus utile ?','Which improvement would help most?','Qual melhoria seria mais útil?','¿Qué mejora sería más útil?'),[('temps',('Enrichir les données disponibles','Enrich available data','Enriquecer os dados disponíveis','Enriquecer los datos disponibles')),('fiabilite',('Fiabiliser les informations','Make information reliable','Tornar as informações confiáveis','Mejorar la fiabilidad de la información')),('suivi',('Mieux suivre les dossiers','Track cases better','Acompanhar melhor os processos','Seguir mejor los expedientes')),('partage',('Faciliter le partage','Make sharing easier','Facilitar o compartilhamento','Facilitar el intercambio')),('inconnu',('À préciser ensemble','To clarify together','A definir em conjunto','Por concretar juntos'))],False,True),
